-- 400: Original BrillaPrep NSMQ riddles beta content (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_400_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_400_guard;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_011' AND NOT (r.subject_id IS 'subj_nsmq_math' AND r.answer IS 'Prime number' AND r.clue_1 IS 'I am a whole number greater than one' AND r.clue_2 IS 'I have exactly two factors: one and myself' AND r.clue_3 IS 'Two is my smallest member and the only even one' AND r.clue_4 IS 'Euclid proved that my family is infinite' AND r.clue_5 IS 'Modern encryption multiplies large members of my family together' AND r.difficulty IS 'easy')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_012' AND NOT (r.subject_id IS 'subj_nsmq_math' AND r.answer IS 'Imaginary unit i' AND r.clue_1 IS 'I am a number, yet I am not real' AND r.clue_2 IS 'Squaring me produces a negative result' AND r.clue_3 IS 'My square is exactly minus one' AND r.clue_4 IS 'Electrical engineers write me as j in circuit analysis' AND r.clue_5 IS 'Euler’s identity links me with e and π' AND r.difficulty IS 'hard')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_013' AND NOT (r.subject_id IS 'subj_nsmq_physics' AND r.answer IS 'Inertia' AND r.clue_1 IS 'I am a resistance to change' AND r.clue_2 IS 'Newton’s first law of motion describes me' AND r.clue_3 IS 'Mass is the measure of me' AND r.clue_4 IS 'You feel me when a moving bus suddenly brakes' AND r.clue_5 IS NULL AND r.difficulty IS 'medium')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_014' AND NOT (r.subject_id IS 'subj_nsmq_physics' AND r.answer IS 'Electron' AND r.clue_1 IS 'I am a subatomic particle' AND r.clue_2 IS 'I carry a negative electric charge' AND r.clue_3 IS 'J. J. Thomson discovered me in 1897' AND r.clue_4 IS 'My drift through a wire is an electric current' AND r.clue_5 IS 'My charge is about −1.6 × 10⁻¹⁹ coulombs' AND r.difficulty IS 'easy')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_015' AND NOT (r.subject_id IS 'subj_nsmq_chemistry' AND r.answer IS 'Periodic table' AND r.clue_1 IS 'I am a chart, not a piece of furniture' AND r.clue_2 IS 'I organise all known chemical elements' AND r.clue_3 IS 'Mendeleev published my first recognisable form in 1869' AND r.clue_4 IS 'My rows are called periods and my columns are called groups' AND r.clue_5 IS 'Elements in the same column of mine tend to react alike' AND r.difficulty IS 'easy')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_016' AND NOT (r.subject_id IS 'subj_nsmq_chemistry' AND r.answer IS 'Catalyst' AND r.clue_1 IS 'I make a chemical reaction go faster' AND r.clue_2 IS 'I am not consumed in the reaction' AND r.clue_3 IS 'I work by providing a path of lower activation energy' AND r.clue_4 IS 'Enzymes are my biological relatives' AND r.clue_5 IS 'Catalytic converters in car exhausts contain me' AND r.difficulty IS 'medium')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_017' AND NOT (r.subject_id IS 'subj_nsmq_chemistry' AND r.answer IS 'pH' AND r.clue_1 IS 'I am a number that tells you how acidic something is' AND r.clue_2 IS 'My usual scale runs from 0 to 14' AND r.clue_3 IS 'Seven on my scale means neutral' AND r.clue_4 IS 'Litmus paper changes colour because of what I measure' AND r.clue_5 IS 'I am the negative logarithm of the hydrogen-ion concentration' AND r.difficulty IS 'medium')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_018' AND NOT (r.subject_id IS 'subj_nsmq_biology' AND r.answer IS 'Chlorophyll' AND r.clue_1 IS 'I am a pigment' AND r.clue_2 IS 'I make leaves look green' AND r.clue_3 IS 'I absorb mainly red and blue light' AND r.clue_4 IS 'Photosynthesis cannot proceed without me' AND r.clue_5 IS 'I sit in the thylakoid membranes inside chloroplasts' AND r.difficulty IS 'easy')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_019' AND NOT (r.subject_id IS 'subj_nsmq_biology' AND r.answer IS 'Neuron' AND r.clue_1 IS 'I am a cell that carries messages' AND r.clue_2 IS 'My signals are both electrical and chemical' AND r.clue_3 IS 'I have dendrites that receive and an axon that transmits' AND r.clue_4 IS 'I pass information across junctions called synapses' AND r.clue_5 IS 'Some of my kind run from your spinal cord to your toes' AND r.difficulty IS 'medium')) THEN 1 ELSE 0 END;
INSERT INTO _migration_400_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM riddles r WHERE r.id = 'riddle_020' AND NOT (r.subject_id IS 'subj_nsmq_biology' AND r.answer IS 'Ribosome' AND r.clue_1 IS 'I am a tiny machine inside every cell' AND r.clue_2 IS 'I am built from RNA and protein' AND r.clue_3 IS 'I read messenger RNA codon by codon' AND r.clue_4 IS 'I am the site of protein synthesis' AND r.clue_5 IS 'I float free in the cytoplasm or stud the rough endoplasmic reticulum' AND r.difficulty IS 'hard')) THEN 1 ELSE 0 END;
